228	async fn confirm(
229	    user: AuthenticatedUser,
230	    state: &AppState,
231	    req: &ClaimConfirmRequest,
232	) -> Result<Response, AgentAuthError> {
233	    // Only the account holder's own full-access credential may confirm. App-password tokens
234	    // (narrower scope) are refused by the scope check; agent-derived tokens map to `Access` for
235	    // coarse admission, so `is_agent` closes the gap — an agent must never confirm itself.
236	    if user.scope != AuthScope::Access {
237	        return Err(AgentAuthError::new(
238	            StatusCode::UNAUTHORIZED,
239	            "invalid_token",
240	            "a full-access token is required to confirm an agent claim",
241	        ));
242	    }
243	    if user.is_agent() {
244	        return Err(AgentAuthError::new(
245	            StatusCode::FORBIDDEN,
246	            "access_denied",
247	            "agent-derived credentials cannot confirm a claim",
248	        ));
249	    }
250	
251	    let user_code = req
252	        .user_code
253	        .as_deref()
254	        .filter(|s| !s.is_empty())
255	        .ok_or_else(|| {
256	            AgentAuthError::new(
257	                StatusCode::BAD_REQUEST,
258	                "invalid_request",
259	                "missing required field: user_code",
260	            )
261	        })?;
262	
263	    // Brute-forcing the `user_code` is bounded by the tight per-endpoint IP limiter this route
264	    // shares with `/v1/agents/claim-preview` (`rate_limit.rs`, `agent_claim_confirm_per_5min` —
265	    // the same short-code posture as `/v1/transfer/accept`), on top of the full-access auth
266	    // requirement — so the guessing surface is an *authenticated* caller racing a ~36^6-wide code
267	    // within its short TTL and a shared per-IP budget (and success only lets them bind an
268	    // ownerless anonymous registration to their own account, not take over a victim's).
269	    let attempt = get_agent_claim_attempt_by_user_code(&state.db, user_code)
270	        .await?
271	        .ok_or_else(|| {
272	            AgentAuthError::new(
273	                StatusCode::BAD_REQUEST,
274	                "invalid_user_code",
275	                "the user code is unknown",
276	            )
277	        })?;
278	    if !attempt.is_pending() {
279	        // An already-consumed attempt is `claimed_or_in_flight`; anything else non-pending (swept
280	        // expired, or pending-but-past-expiry) is a lapsed code.
281	        return Err(if attempt.status == ClaimAttemptStatus::Completed {
282	            AgentAuthError::new(
283	                StatusCode::BAD_REQUEST,
284	                "claimed_or_in_flight",
285	                "this user code has already been used",
286	            )
287	        } else {
288	            AgentAuthError::new(
289	                StatusCode::BAD_REQUEST,
290	                "claim_expired",
291	                "the user code has expired; restart the claim",
292	            )
293	        });
294	    }
295	
296	    let identity = get_agent_identity(&state.db, &attempt.identity_id)
297	        .await?
298	        .ok_or_else(AgentAuthError::server_error)?;
299	
300	    if let Some(req_reg) = req.registration_id.as_deref().filter(|s| !s.is_empty()) {
301	        if req_reg != identity.id {
302	            return Err(AgentAuthError::new(
303	                StatusCode::BAD_REQUEST,
304	                "invalid_request",
305	                "registration_id does not match this user code",
306	            ));
307	        }
308	    }
309	
310	    match identity.status {
311	        AgentIdentityStatus::Claimed => {
312	            return Err(AgentAuthError::new(
313	                StatusCode::BAD_REQUEST,
314	                "claimed_or_in_flight",
315	                "this registration has already been claimed",
316	            ));
317	        }
318	        AgentIdentityStatus::Revoked => {
319	            return Err(AgentAuthError::new(
320	                StatusCode::FORBIDDEN,
321	                "access_denied",
322	                "this agent identity has been revoked",
323	            ));
324	        }
325	        AgentIdentityStatus::Active => {}
326	    }
327	
328	    // Authorization. A registration already bound to an owner (service_auth / identity_assertion)
329	    // may be confirmed only by that owner. An ownerless anonymous registration is bound to whoever
330	    // completes the ceremony — the `user_code` they were shown is the authorization.
331	    let bind_did = match identity.did.as_deref() {
332	        Some(bound) => {
333	            if bound != user.did {
334	                return Err(AgentAuthError::new(
335	                    StatusCode::FORBIDDEN,
336	                    "access_denied",
337	                    "this claim is bound to a different account",
338	                ));
339	            }
340	            None
341	        }
342	        None => Some(user.did.as_str()),
343	    };
344	
345	    // The post-claim assertion carries the operator's current full granted-scope profile. Normalize
346	    // it into a deterministic, deduplicated set so this mint matches the `identity_assertion` mint
347	    // path byte-for-byte: `intersect_scope_tokens(xs, xs)` is the crate's canonicalizer — it returns
348	    // the tokens of `xs` sorted and deduped (a self-intersection, since every token is in both
349	    // operands). There is no separate infallible canonicalizer helper; `canonicalize_agent_scopes`
350	    // is the fallible startup validator, not this hot path.
351	    let granted = &state.config.agent_auth.granted_scopes;
352	    let scopes = intersect_scope_tokens(granted, granted);
353	    let minted = mint_identity_assertion(
354	        &state.oauth_signing_keypair,
355	        &state.config.public_url,
356	        state.config.agent_auth.assertion_ttl_secs,
357	        &user.did,
358	        &identity.id,
359	        identity.registration_type.as_str(),
360	        &scopes,
361	    )?;
362	    let scopes_json = scopes_to_json(&scopes);
363	
364	    // One transaction: consume the pending attempt, then claim the identity. Each write carries its
365	    // own guard (`status = 'pending'` / `status = 'active'`), so a lost race rolls back cleanly
366	    // rather than double-claiming. Every read (and the pure mint) ran before `begin()` — the
367	    // single-connection pool cannot serve a `&SqlitePool` read while a transaction holds the
368	    // connection.
369	    let mut tx = state.db.begin().await.map_err(|e| {
370	        tracing::error!(error = %e, "failed to open transaction for agent claim confirm");
371	        AgentAuthError::server_error()
372	    })?;
373	    if !complete_agent_claim_attempt(&mut *tx, &attempt.id).await? {
374	        return Err(AgentAuthError::new(
375	            StatusCode::CONFLICT,
376	            "claimed_or_in_flight",
377	            "this claim attempt is no longer pending",
378	        ));
379	    }
380	    if !claim_agent_identity(
381	        &mut *tx,
382	        &identity.id,
383	        bind_did,
384	        &scopes_json,
385	        &minted.jwt,
386	        &minted.expires_sqlite,
387	    )
388	    .await?
389	    {
390	        return Err(AgentAuthError::new(
391	            StatusCode::CONFLICT,
392	            "claimed_or_in_flight",
393	            "this registration is no longer active",
394	        ));
395	    }
396	    // The confirmation audit row commits atomically with the claim itself: the human gate is the
397	    // audit trail's anchor event, so it must never be missing from a claimed identity's history.
398	    let confirm_detail = serde_json::json!({
399	        "claim_attempt_id": attempt.id,
400	        "scopes": scopes,
401	    })
402	    .to_string();
403	    crate::db::agent_audit::insert_agent_audit_event(
404	        &mut *tx,
405	        &uuid::Uuid::new_v4().to_string(),
406	        &identity.id,
407	        Some(&user.did),
408	        crate::db::agent_audit::AgentAuditEventType::ClaimConfirmed,
409	        Some(&confirm_detail),
410	    )
411	    .await?;
412	    tx.commit().await.map_err(|e| {
413	        tracing::error!(error = %e, "failed to commit agent claim confirm");
414	        AgentAuthError::server_error()
415	    })?;
416	
417	    Ok((
418	        StatusCode::OK,
419	        Json(ClaimConfirmResponse {
420	            registration_id: identity.id,
421	            status: "claimed",
422	            did: user.did,
423	        }),
424	    )
425	        .into_response())
426	}

