56	impl FromRequestParts<AppState> for AuthenticatedUser {
57	    type Rejection = ApiError;
58	
59	    async fn from_request_parts(
60	        parts: &mut Parts,
61	        state: &AppState,
62	    ) -> Result<Self, Self::Rejection> {
63	        // 1. Extract the access token from the Authorization header. Both schemes
64	        //    are accepted here (RFC 9449 §7.1): a DPoP-bound OAuth token arrives as
65	        //    `Authorization: DPoP <token>`, a plain session/agent token as
66	        //    `Authorization: Bearer <token>`. Scheme ↔ binding consistency is
67	        //    enforced below, after the token's claims are decoded.
68	        let (scheme, token_str) = extract_access_token(&parts.headers)?;
69	
70	        // 2. Detect the DPoP header before decoding the access token.
71	        //    RFC 9449 §11.1: reject if multiple DPoP headers are present — a
72	        //    header-prepending proxy could inject a forged proof as the first value.
73	        if parts.headers.get_all("DPoP").iter().count() > 1 {
74	            return Err(ApiError::new(
75	                common::ErrorCode::InvalidToken,
76	                "multiple DPoP headers are not permitted",
77	            ));
78	        }
79	        let dpop_value = parts
80	            .headers
81	            .get("DPoP")
82	            .and_then(|v| {
83	                v.to_str()
84	                    .inspect_err(|_| {
85	                        tracing::warn!("DPoP header contains non-UTF-8 bytes; treating as absent");
86	                    })
87	                    .ok()
88	            })
89	            .map(str::to_owned);
90	        let has_dpop = dpop_value.is_some();
91	
92	        // 3. Decode and verify the access token (HS256 or ES256).
93	        let claims = verify_access_token(token_str, state)?;
94	
95	        // 4. Enforce DPoP binding and scheme ↔ binding consistency (RFC 9449 §7.1).
96	        //    The authorization scheme *declares* the token's binding regime, so a
97	        //    mismatch in either direction is rejected rather than downgraded:
98	        //    * `cnf` present but no `jkt` → explicit rejection: a future cnf variant
99	        //      (e.g. `x5t#S256` for cert binding) could be silently downgraded to plain
100	        //      Bearer if we only check `jkt.is_some()`.
101	        //    * `cnf.jkt` present but no DPoP header → downgrade attack; reject.
102	        //    * `cnf.jkt` present but presented as `Bearer` → a bound token used
103	        //      without declaring its binding (matches the reference PDS rejection).
104	        //    * `DPoP` scheme but an unbound token → the client claims
105	        //      proof-of-possession the token doesn't carry; reject.
106	        if let Some(cnf) = &claims.cnf {
107	            if cnf.jkt.is_none() {
108	                return Err(ApiError::new(
109	                    common::ErrorCode::InvalidToken,
110	                    "access token cnf present without jkt binding",
111	                ));
112	            }
113	            if !has_dpop {
114	                return Err(ApiError::new(
115	                    common::ErrorCode::InvalidToken,
116	                    "DPoP-bound token requires a DPoP proof header",
117	                ));
118	            }
119	            if scheme != AuthScheme::Dpop {
120	                return Err(ApiError::new(
121	                    common::ErrorCode::InvalidToken,
122	                    "DPoP-bound token must use the DPoP authorization scheme",
123	                ));
124	            }
125	        } else if scheme == AuthScheme::Dpop {
126	            return Err(ApiError::new(
127	                common::ErrorCode::InvalidToken,
128	                "DPoP authorization scheme requires a DPoP-bound access token",
129	            ));
130	        }
131	
132	        // 5. Resolve scope enum.
133	        let scope = parse_scope(&claims.scope)?;
134	
135	        // 6. DPoP proof validation — only when the DPoP header is present.
136	        if has_dpop {
137	            let dpop_token = dpop_value.as_deref().unwrap();
138	            validate_dpop(
139	                dpop_token,
140	                &parts.method,
141	                &parts.uri,
142	                &state.config.public_url,
143	                &claims,
144	                token_str,
145	            )?;
146	        }
147	
148	        Ok(AuthenticatedUser {
149	            did: claims.sub,
150	            scope,
151	            scope_claim: claims.scope,
152	            registration_id: claims.registration_id,
153	        })
154	    }
155	}
