        return Err(OwnerAuthError::AgentDerived);
    }
    let scope =
        crate::auth::jwt::parse_scope(&claims.scope).map_err(OwnerAuthError::Unauthenticated)?;
    if scope != crate::auth::jwt::AuthScope::Access {
        return Err(OwnerAuthError::NotFullAccess);
    }
